import types

# Check if add_ten exists and is a lambda
if 'add_ten' not in locals():
    raise AssertionError('Task 1: add_ten variable not found')

if not isinstance(add_ten, types.LambdaType):
    raise AssertionError('Task 1: add_ten should be a lambda function')

# Test the function
if add_ten(5) != 15:
    raise AssertionError('Task 1: add_ten(5) should return 15')
if add_ten(0) != 10:
    raise AssertionError('Task 1: add_ten(0) should return 10')

print('TEST_PASSED')

if 'fahrenheit' not in locals():
    raise AssertionError('Task 3: fahrenheit variable not found')

# Check if it's a map object (lazy evaluation is fine)
if not hasattr(fahrenheit, '__iter__'):
    raise AssertionError('Task 3: fahrenheit should be an iterable (map object)')

# Convert to list for testing
f_list = list(fahrenheit)
expected = [32.0, 68.0, 86.0, 98.6, 212.0]

if len(f_list) != len(expected):
    raise AssertionError(f'Task 3: Expected {len(expected)} values, got {len(f_list)}')

for i, (actual, exp) in enumerate(zip(f_list, expected)):
    if abs(actual - exp) > 0.1:
        raise AssertionError(f'Task 3: Value {i} should be {exp}, got {actual}')

print('TEST_PASSED')
